type TagSelectItem = {
  id: React.Key;
  [key: string]: unknown;
};

type TagSelectItemOwnProps = {
  disabled?: boolean;
  textValue?: string;
};

type TagSelectOwnProps<T extends TagSelectItem = TagSelectItem> = {
  size?: 'sm' | 'md' | 'lg';
  label?: React.ReactNode;
  placeholder?: string;
  description?: React.ReactNode;
  errorMessage?: React.ReactNode;
  disabled?: boolean;
  required?: boolean;
  invalid?: boolean;
  items?: T[];
  selectedKeys?: Set<React.Key>;
  defaultSelectedKeys?: Set<React.Key>;
  onSelectionChange?: (keys: Set<React.Key>) => void;
  getItemLabel?: (item: T) => string;
};

type TagSelectProps<T extends TagSelectItem = TagSelectItem> = Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> & TagSelectOwnProps<T> & {
  children?: React.ReactNode | ((item: T) => React.ReactNode);
  readOnly?: boolean;
};

interface TagSelectRootComponent {
  <T extends TagSelectItem = TagSelectItem>(props: TagSelectRootProps<T> & React.RefAttributes<HTMLDivElement>): React.ReactElement | null;
}
